// Portable SOURCE + semantic-meta DATA. Private compiler receipts are rebuilt,
// never serialized, guessed or restored from hashes/public flags.
import {posix} from 'node:path';
import {translateProjectOrderedTextMaps,withOrderedTextMapCallerSources} from './ordered-text-map-callers-20261102-project.mjs';
