export function readOrderedMapReverseSourceCapsule(text){
 const value=envelope(text,'reverse'),packet=reversePacket(value.source);return scopes(packet,()=>rules('cold-map-reverse-original-native-context-and-meta-reissue',()=>{concreteFiles(packet,false);return readOrderedTextMapReverseMeta(value.meta,{input:packet.input,path:packet.path});},program=>({program,rust:emitOrderedTextMapReverseProgram(program,'rust'),typescript:emitOrderedTextMapReverseProgram(program,'typescript',{outputPath:packet.path.replace(/\.[^/.]+$/u,'.mts')}),...report()})));
}
